import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { describe, expect, it } from 'vitest';
import { CHARACTERS, FURNITURE, GENERIC_CHARACTER, OFFICE_EXTRAS } from '..';

// The art is generated by scripts/office-art/build-office-art.mjs. These tests
// run the generator in memory and hold the committed outputs to it, so a
// generator change without a rebuild (or a hand-edited sheet) fails here.
const REPO_ROOT = join(__dirname, '..', '..', '..', '..', '..');
const OFFICE_DIR = join(REPO_ROOT, 'src', 'renderer', 'assets', 'office');
const GENERATOR = pathToFileURL(join(REPO_ROOT, 'scripts', 'office-art', 'build-office-art.mjs')).href;
const RASTER = pathToFileURL(join(REPO_ROOT, 'scripts', 'office-art', 'raster.mjs')).href;

interface RasterLayer {
  w: number;
  h: number;
}
interface Rendered {
  built: { fSheet: RasterLayer; cSheet: RasterLayer };
  files: Record<'furniture.png' | 'characters.png' | 'layout.generated.ts', Buffer | string>;
}
interface RasterKit {
  crop: (src: RasterLayer, x: number, y: number, w: number, h: number) => RasterLayer;
  bounds: (layer: RasterLayer) => { w: number; h: number };
}

async function render(): Promise<Rendered> {
  const generator = (await import(/* @vite-ignore */ GENERATOR)) as { renderAll: () => Rendered };
  return generator.renderAll();
}

const lf = (text: string) => text.replace(/\r\n/g, '\n');

describe('office art pipeline', () => {
  it('the committed sheets and layout match a fresh in-memory build', async () => {
    const { files } = await render();
    for (const name of ['furniture.png', 'characters.png'] as const) {
      const committed = readFileSync(join(OFFICE_DIR, name));
      expect(Buffer.compare(committed, files[name] as Buffer), `${name} is stale; rerun the generator`).toBe(0);
    }
    const layout = readFileSync(join(OFFICE_DIR, 'layout.generated.ts'), 'utf8');
    expect(lf(layout)).toBe(lf(files['layout.generated.ts'] as string));
  }, 30_000);

  it('every sprite and character frame has at least one opaque pixel', async () => {
    const { built } = await render();
    const { crop, bounds } = (await import(/* @vite-ignore */ RASTER)) as RasterKit;
    const sheets = new Map<string, RasterLayer>();
    sheets.set(FURNITURE.desk.src, built.fSheet);
    sheets.set(GENERIC_CHARACTER.frames.sit.src, built.cSheet);
    const refs = [
      ...Object.entries(FURNITURE),
      ...Object.entries(OFFICE_EXTRAS),
      ...[...CHARACTERS, GENERIC_CHARACTER].flatMap((c) =>
        Object.entries(c.frames).map(([pose, s]) => [`${c.id}.${pose}`, s] as const),
      ),
    ];
    for (const [name, s] of refs) {
      const sheet = sheets.get(s.src);
      expect(sheet, name).toBeDefined();
      expect(bounds(crop(sheet!, s.x, s.y, s.w, s.h)).w, `${name} is empty`).toBeGreaterThan(0);
    }
  }, 30_000);
});
